-- Row Level Security Policies
DO $rebase_admin_role$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'rebase_admin') THEN
        CREATE ROLE rebase_admin NOLOGIN NOSUPERUSER NOBYPASSRLS NOINHERIT;
    END IF;
EXCEPTION
    WHEN duplicate_object OR unique_violation THEN NULL;
    WHEN insufficient_privilege THEN
        RAISE EXCEPTION 'Rebase writes its server-or-admin policies TO rebase_admin, which does not exist, and % may not create it.', current_user
            USING HINT = 'Run CREATE ROLE rebase_admin NOLOGIN; as an administrator, or declare database({ rls: { adminPolicies: "public" } }) (REBASE_RLS_ADMIN_POLICIES=public) to write them TO public.';
END
$rebase_admin_role$;

DO $rebase_companion$ BEGIN IF EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'app' AND p.tablename = 'app_items' AND p.policyname = 'app_items_default_admin_read_ar_27a0b94c' AND NOT (p.cmd = 'SELECT' AND p.permissive = 'PERMISSIVE' AND p.roles = ARRAY['rebase_admin_request']::name[] AND COALESCE(p.qual, 'true') = 'true' AND COALESCE(p.with_check, 'true') = 'true')) THEN EXECUTE 'DROP POLICY "app_items_default_admin_read_ar_27a0b94c" ON "app"."app_items"'; END IF; END $rebase_companion$;
DROP POLICY IF EXISTS "app_items_default_admin_read" ON "app"."app_items";
CREATE POLICY "app_items_default_admin_read" ON "app"."app_items" AS PERMISSIVE FOR SELECT TO "rebase_admin" USING ((SELECT (rebase.uid() IS NULL) OR (string_to_array(rebase.roles(), ',') && ARRAY['admin'])));
DO $rebase_companion$ BEGIN IF EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'app' AND p.tablename = 'app_items' AND p.policyname = 'app_items_default_admin_write_insert_ar_518a8a65' AND NOT (p.cmd = 'INSERT' AND p.permissive = 'PERMISSIVE' AND p.roles = ARRAY['rebase_admin_request']::name[] AND COALESCE(p.qual, 'true') = 'true' AND COALESCE(p.with_check, 'true') = 'true')) THEN EXECUTE 'DROP POLICY "app_items_default_admin_write_insert_ar_518a8a65" ON "app"."app_items"'; END IF; END $rebase_companion$;
